'use strict';
const OutboundCenter={
 tabs(view){return `<div class="business-toolbar outbound-tabs"><a class="button ${view==='loads'?'primary':'secondary'}" href="/outbounds">装车与审批</a><a class="button ${view==='shipments'?'primary':'secondary'}" href="/outbounds?view=shipments">发运记录与装箱单查询</a>${Business.can('packing-template:write')?`<a class="button ${view==='templates'?'primary':'secondary'}" href="/outbounds/templates">Packing List 模板编辑</a>`:''}</div>`;},
 canonical(path){if(location.pathname+location.search!==path){history.replaceState({},'',path);Router.current=path.split('?')[0];}document.querySelector('.breadcrumb strong').textContent='出库管理';document.querySelectorAll('[data-primary-route]').forEach(a=>{a.classList.toggle('nav-active',a.dataset.primaryRoute==='outbounds');if(a.dataset.primaryRoute==='outbounds')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});},
 links(){for(const a of document.querySelectorAll('#page-content a[href^="/export-shipments"]')){const u=new URL(a.href);a.href=u.pathname==='/export-shipments'?'/outbounds?view=shipments'+(u.search?'&'+u.search.slice(1):''):'/outbounds/packing-list/'+u.pathname.split('/').pop();}},
 async shipments(){const q=new URLSearchParams(location.search);q.set('view','shipments');this.canonical('/outbounds?'+q);await originalShipmentList();$('business-title').textContent='出库管理';document.title='出库管理 · 发运记录与装箱单查询 · V'+AppConfig.version;$('page-content').insertAdjacentHTML('afterbegin',this.tabs('shipments'));this.links();const filter=$('shipping-filter');filter.insertAdjacentHTML('beforeend','<input type="hidden" name="view" value="shipments">');Shipping.bindFilters('/outbounds');Shipping.bindPaging({page:Number(new URLSearchParams(location.search).get('page')||1)},'/outbounds');},
 async templates(){const d=await API.request('/shipping/templates');Router.page('Packing List 模板编辑',this.tabs('templates')+`<p>在此编辑表头、公司信息和固定文字。客户、计划、捆包及重量仍由业务记录自动读取。保存后用于新生成的 Packing List，已生成单证保持原修订，可按需重新生成。</p><p>当前模板：<strong>${d.revision?'r'+d.revision:'系统原始模板'}</strong></p><form id="packing-template-form" class="user-form"><h3>公司信息与标题</h3><div class="form-grid">${d.fields.slice(0,9).map(this.field).join('')}</div><details class="lp-load-summary"><summary>其他表头、声明与签字文字</summary><div class="form-grid">${d.fields.slice(9).map(this.field).join('')}</div></details><label>修改原因<textarea name="reason" required minlength="5" maxlength="1000"></textarea></label><p class="error" id="template-error" role="alert"></p><div class="business-toolbar"><button type="button" id="template-preview" class="button secondary">预览模板</button><button class="button primary">保存并启用</button><button type="button" id="template-original" class="button secondary">恢复系统原始模板</button></div></form><details class="lp-load-summary"><summary>模板修改记录</summary>${d.history.map(h=>`<p><strong>r${h.revision}</strong> · <span data-no-i18n>${esc(h.created_by_name)} · ${esc(new Date(h.created_at).toLocaleString())} · ${esc(h.reason)}</span> <button class="button secondary" data-template-restore="${h.id}">恢复此版本</button></p>`).join('')||'<p>尚无模板修改记录</p>'}</details><h3>模板预览（示例，不是正式单证）</h3><div id="packing-list-preview" class="packing-list-preview"></div>`);
 const form=$('packing-template-form'),fields=()=>Object.fromEntries(d.fields.map(f=>[f.address,form.elements['cell_'+f.address].value]));$('template-preview').onclick=async e=>{e.target.disabled=true;try{const r=await API.request('/shipping/templates/preview',{method:'POST',body:{version:d.version,fields:fields()}});Shipping.drawPreview(r.layout);$('template-error').textContent='';}catch(err){$('template-error').textContent=err.message;}finally{e.target.disabled=false;}};
 const save=async(extra,button)=>{button.disabled=true;try{const reason=form.elements.reason.value;if(reason.trim().length<5)throw Error('修改原因至少5个字');await API.request('/shipping/templates',{method:'POST',body:{version:d.version,reason,...extra}});await this.templates();notify('模板已启用；历史单证保持原修订');}catch(err){$('template-error').textContent=err.message;button.disabled=false;}};form.onsubmit=e=>{e.preventDefault();save({fields:fields()},e.submitter);};$('template-original').onclick=e=>save({restore_original:true},e.target);document.querySelectorAll('[data-template-restore]').forEach(b=>b.onclick=()=>save({restore_id:b.dataset.templateRestore},b));
 },
 field(f){return `<label>${esc(f.label)}<small data-no-i18n> ${f.address}</small><textarea name="cell_${f.address}" maxlength="2000" data-no-i18n>${esc(f.value)}</textarea></label>`;}
};
const originalShipmentList=Shipping.list.bind(Shipping),originalLoadingList=Flow.loads.bind(Flow),originalPackingDetail=Shipping.detail.bind(Shipping);
Shipping.list=()=>OutboundCenter.shipments();
Shipping.detail=async function(id){OutboundCenter.canonical('/outbounds/packing-list/'+id);await originalPackingDetail(id);$('page-content').insertAdjacentHTML('afterbegin',OutboundCenter.tabs('shipments'));OutboundCenter.links();};
Flow.loads=Flow.outbounds=async function(){if(new URLSearchParams(location.search).get('view')==='shipments')return OutboundCenter.shipments();await originalLoadingList();$('page-content').insertAdjacentHTML('afterbegin',OutboundCenter.tabs('loads'));OutboundCenter.links();};
delete Router.names['export-shipments'];
const centerPermission=Router.permission.bind(Router);Router.permission=p=>p==='/outbounds/templates'?'packing-template:write':centerPermission(p);
const centerInit=Router.init.bind(Router);Router.init=async function(){this.add(/^\/outbounds\/templates$/,()=>OutboundCenter.templates());this.add(/^\/outbounds\/packing-list\/([0-9a-f-]{36})$/,id=>Shipping.detail(id));const r=await centerInit();document.querySelectorAll('[data-primary-route="export-shipments"]').forEach(a=>a.remove());return r;};
Accounts.groups['packing-template']='出库管理';Accounts.permissionLabels['packing-template:write']='Packing List 模板编辑与启用';
